/* atax.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"


/* Array initialization.
 *
 * Optimizations:
 * - Precompute reciprocals to avoid repeated divisions.
 * - Keep row-major traversal of A for good cache locality.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Precompute reciprocals once instead of dividing in every iteration. */
  const DATA_TYPE inv_fn  = SCALAR_VAL(1.0) / fn;
  const DATA_TYPE inv_5m  =
    SCALAR_VAL(1.0) / (SCALAR_VAL(5.0) * (DATA_TYPE)m);

  /* Initialize x: x[i] = 1 + (i / n). */
  for (i = 0; i < n; i++)
    x[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i) * inv_fn;

  /* Initialize A with a simple modular pattern.
   * Accesses are in row-major order to exploit spatial locality.
   */
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
    {
      int v = (i + j) % n;
      A[i][j] = ((DATA_TYPE)v) * inv_5m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original computation:
 *   tmp[i] = sum_j A[i][j] * x[j];
 *   y[j]  += sum_i A[i][j] * tmp[i];
 *
 * Optimizations:
 * - Introduce `restrict`-qualified local pointers to convey non-aliasing
 *   information to the compiler, enabling better vectorization.
 * - Use a scalar accumulator `t` for tmp[i] to reduce memory traffic
 *   (tmp[i] is written once per i instead of on every inner iteration).
 * - Use a single OpenMP parallel region to:
 *     * initialize y in parallel,
 *     * distribute rows of A (loop over i) across threads, and
 *     * handle accumulation into y via an OpenMP array reduction.
 *   When compiled without -fopenmp, all OpenMP pragmas are ignored and
 *   the code executes sequentially with the same algorithmic behavior.
 * - Add `#pragma omp simd` to guide vectorization of inner loops
 *   (compilers may already do this at -O3, but the directive makes
 *    the intent explicit).
 */
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Create local restricted pointers to help the optimizer reason
     about aliasing. We only use these restricted views below. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

#pragma scop
  /* Use a single parallel region to amortize OpenMP startup costs.
     Without -fopenmp, all `#pragma omp` lines are ignored and this
     block simply executes sequentially. */
#pragma omp parallel private(i, j)
  {
    /* 1) Initialize y to zero.
       This loop is independent across iterations and easily parallelized. */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; i++)
      y_[i] = SCALAR_VAL(0.0);

    /* 2) Main ATAX computation.
       Each iteration over i uses row i of A and updates tmp[i] and y.
       The updates to y are handled through an OpenMP array reduction
       to keep the operation thread-safe while preserving the same
       mathematical result (up to floating-point associativity). */
#pragma omp for schedule(static) reduction(+: y_[:_PB_N])
    for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE t = SCALAR_VAL(0.0);
      DATA_TYPE *restrict Ai = A_[i];

      /* Compute tmp[i] = sum_j A[i][j] * x[j].
         The reduction on `t` enables efficient SIMD code generation. */
#pragma omp simd reduction(+: t)
      for (j = 0; j < _PB_N; j++)
        t += Ai[j] * x_[j];

      /* Store tmp[i] once per row. This preserves the original
         tmp array semantics while avoiding repeated loads/stores
         in the inner loops. */
      tmp_[i] = t;

      /* Accumulate into y: y[j] += A[i][j] * tmp[i].
         This loop is also vectorizable. */
#pragma omp simd
      for (j = 0; j < _PB_N; j++)
        y_[j] += Ai[j] * t;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
