 *
 * Contact:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* atax.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for OpenMP parallelization pragmas */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"

/* Tunable parameter: minimal total work (in A elements) before
 * enabling OpenMP parallelization in the main kernel.
 * Adjust this to match the target machine.
 */
#ifndef ATAX_OMP_MIN_NNZ
# define ATAX_OMP_MIN_NNZ 32768UL
#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  /* Precompute reciprocals to replace repeated divisions with
   * cheaper multiplications.  This is mathematically equivalent
   * to the original code but reduces the number of FP divisions.
   */
  const DATA_TYPE inv_fn =
    SCALAR_VAL(1.0) / fn;
  const DATA_TYPE a_scale =
    SCALAR_VAL(1.0) / (SCALAR_VAL(5.0) * (DATA_TYPE)m);

  /* Initialize x: each element is independent, so the loop can be
   * safely parallelized. The OpenMP pragma is ignored if the code
   * is compiled without -fopenmp.
   */
#pragma omp parallel for schedule(static) if (n >= 1024)
  for (i = 0; i < n; i++)
    x[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i) * inv_fn;
    /* Same as: 1 + ( (DATA_TYPE)i / fn ) */

  /* Initialize A: each element is also independent. We parallelize
   * the 2D loop using collapse(2) so both i and j are distributed
   * across threads.  Access pattern remains row-major.
   */
#pragma omp parallel for collapse(2) schedule(static) if ((size_t)m * (size_t)n >= ATAX_OMP_MIN_NNZ)
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE)((i + j) % n)) * a_scale;
      /* Same as: (DATA_TYPE)((i+j)%n) / (5*m) */
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original algorithm:
     tmp[i] = sum_j A[i][j] * x[j];
     y[j]   = sum_i A[i][j] * tmp[i];

   This implementation keeps the same mathematical computation but:
     - improves locality by keeping row pointers in a scalar
     - uses OpenMP to parallelize the outer loop over i
     - uses an OpenMP array section reduction on y to avoid races
     - adds explicit SIMD hints for inner j loops
*/
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Create local restrict-qualified pointers to help the compiler
   * with alias analysis and vectorization, without changing the
   * externally visible API.
   */
  DATA_TYPE * __restrict x_   = x;
  DATA_TYPE * __restrict y_   = y;
  DATA_TYPE * __restrict tmp_ = tmp;

#pragma scop
  /* Initialize y to 0 as in the original code.  This loop is kept
   * separate so that the following OpenMP reduction has a clean
   * zero starting value.
   */
  for (i = 0; i < _PB_N; i++)
    y_[i] = SCALAR_VAL(0.0);

  /* Total amount of work (number of A-elements touched) used as a
   * heuristic threshold for enabling OpenMP parallelism.
   */
  const size_t total_work = (size_t)_PB_M * (size_t)_PB_N;

  /* Parallelize the outer loop over rows i.
   *
   * Each iteration:
   *   - computes a row-wise dot product tmp_i = A[i][:] · x
   *   - writes tmp[i] (each i is unique, no races)
   *   - accumulates into y[:] via y[j] += A[i][j] * tmp_i
   *
   * The dependence on y is expressed as an array-section reduction,
   * which gives each thread a private copy of y_ and combines them
   * with addition at the end, preserving the serial semantics.
   */
#pragma omp parallel for if (total_work >= ATAX_OMP_MIN_NNZ) \
                         schedule(static) private(j) \
                         reduction(+:y_[0:_PB_N])
  for (i = 0; i < _PB_M; i++)
    {
      /* Pointer to the current row of A, for better locality and
       * to give the compiler a simple base+offset pattern.
       */
      DATA_TYPE * __restrict Ai = A[i];

      DATA_TYPE tmp_i = SCALAR_VAL(0.0);

      /* First phase: tmp_i = sum_j A[i][j] * x[j]
       * The reduction(+:tmp_i) clause makes the loop clearly
       * vectorizable for the compiler.
       */
#pragma omp simd reduction(+:tmp_i)
      for (j = 0; j < _PB_N; j++)
        tmp_i += Ai[j] * x_[j];

      /* Store the final tmp value.  The original code updated
       * tmp[i] every inner iteration; here we only store once
       * per row, which is equivalent because tmp[i] is not read
       * until after the dot product completes.
       */
      tmp_[i] = tmp_i;

      /* Second phase: y[j] += A[i][j] * tmp_i
       * Each j is independent, so we can give a SIMD hint.
       * The array reduction on y_ across the enclosing parallel
       * loop ensures thread safety.
       */
#pragma omp simd
      for (j = 0; j < _PB_N; j++)
        y_[j] += Ai[j] * tmp_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
