/* Array initialization.
 *
 * Optimizations:
 * - Use local restrict-qualified aliases for A and x to help the compiler
 *   with alias analysis.
 * - Hoist the denominator 5*m out of the inner loops to avoid redundant
 *   integer multiplications and conversions, while preserving exact
 *   floating-point semantics (we still divide by the same value).
 * - Use row pointers (Ai) to avoid repeated indexing and improve
 *   cache friendliness.
 */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  /* Local restrict aliases to help the optimizer.  The underlying
     PolyBench allocation guarantees that these arrays do not overlap. */
  DATA_TYPE (* __restrict A_)[N] = (DATA_TYPE (*)[N])A;
  DATA_TYPE * __restrict x_      = (DATA_TYPE *)x;

  const DATA_TYPE fn    = (DATA_TYPE)n;
  const DATA_TYPE denom = SCALAR_VAL(5.0) * (DATA_TYPE)m;

  /* Initialize x. */
  for (i = 0; i < n; i++)
    x_[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i) / fn;

  /* Initialize A.
     We keep the division (rather than precomputing its reciprocal) to
     preserve strict floating-point semantics while avoiding repeated
     integer multiplications. */
  for (i = 0; i < m; i++) {
    DATA_TYPE * __restrict Ai = A_[i];
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE)((i + j) % n)) / denom;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Mathematical operation (ATAx):
 *   tmp = A * x
 *   y   = A^T * tmp
 *
 * Optimizations:
 * - Introduce restrict-qualified local aliases for all arrays to allow
 *   better vectorization and instruction scheduling.
 * - Use a scalar accumulator tmp_i kept in a register instead of
 *   repeatedly reading/writing tmp[i] inside the inner loop.
 * - Use a row pointer Ai = A_[i] to reduce address computation and
 *   improve cache performance.
 * - Express explicit data-parallelism with OpenMP pragmas:
 *     * parallelize the outer loop over rows i with a reduction over y
 *       using an OpenMP array-section reduction
 *     * use #pragma omp simd on inner loops to encourage vectorization
 *
 *   When compiled without OpenMP support (-fopenmp), all #pragma omp
 *   directives are ignored by the compiler, so the code falls back to a
 *   sequential implementation that preserves the original semantics.
 */
static
void kernel_atax [[gnu::flatten, gnu::noinline]] (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n),
                 DATA_TYPE POLYBENCH_1D(y,N,n),
                 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Local restrict aliases.  types:
       A_   : pointer to rows of length N
       x_, y_: 1D arrays of length N
       tmp_ : 1D array of length M
     This informs the compiler that these arrays do not alias each other. */
  DATA_TYPE (* __restrict A_)[N] = (DATA_TYPE (*)[N])A;
  DATA_TYPE * __restrict x_      = (DATA_TYPE *)x;
  DATA_TYPE * __restrict y_      = (DATA_TYPE *)y;
  DATA_TYPE * __restrict tmp_    = (DATA_TYPE *)tmp;

  /* Capture PolyBench problem sizes in local variables to avoid
     re-evaluating macros and to make them available for OpenMP clauses. */
  int n_pb = _PB_N;
  int m_pb = _PB_M;

#pragma scop
  /* Initialize y to zero.  This is separated to keep the reduction
     initialization simple and explicit. */
  for (i = 0; i < n_pb; i++)
    y_[i] = SCALAR_VAL(0.0);

  /* Parallelize the outer loop over rows of A.
     - Each iteration i computes tmp_[i] and contributes A[i][*] * tmp_[i]
       to the global y_ vector.
     - The contributions to y_ are combined using an OpenMP reduction
       over the array section y_[0:n_pb].
     - Without OpenMP, all 'omp' pragmas are ignored and this loop
       executes sequentially with identical semantics. */
#pragma omp parallel for schedule(static) reduction(+:y_[0:n_pb])
  for (i = 0; i < m_pb; i++)
  {
    DATA_TYPE tmp_i = SCALAR_VAL(0.0);
    DATA_TYPE * __restrict Ai = A_[i];

    /* tmp_i = dot(A[i][:], x[:]) */
#pragma omp simd reduction(+:tmp_i)
    for (j = 0; j < n_pb; j++)
      tmp_i += Ai[j] * x_[j];

    /* Store the result in tmp_ as required by the original kernel. */
    tmp_[i] = tmp_i;

    /* y[j] += A[i][j] * tmp_i  for all j.
       Using y_[0:n_pb] as a reduction target ensures correctness when
       the outer loop is parallelized. */
#pragma omp simd
    for (j = 0; j < n_pb; j++)
      y_[j] += Ai[j] * tmp_i;
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
               POLYBENCH_ARRAY(A),
               POLYBENCH_ARRAY(x),
               POLYBENCH_ARRAY(y),
               POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
