  for (i = 0; i < n; i++)
    x[i] = 1 + (i / fn);

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation:

     tmp[i] = sum_j A[i][j] * x[j]
     y[j]   = sum_i A[i][j] * tmp[i]

   i.e., y = A^T * (A * x).

   Optimizations applied:
   - Keep y initialization as a separate pass (trivial cost, good vectorization).
   - Use a scalar accumulator tmp_i instead of repeatedly writing tmp[i] inside
     the inner loop (reduces memory traffic).
   - Write tmp[i] once per row to preserve original live-out semantics.
   - Reuse a row pointer Ai = A[i] to improve data locality and help the
     compiler generate efficient address arithmetic.
   - Add OpenMP parallelization over the outer i-loop with an array
     reduction on y to exploit multi-core systems. If the code is compiled
     without OpenMP support, all pragmas are ignored and the code runs
     sequentially with the same semantics as the original.
   - Add OpenMP 'simd' hints on inner loops to encourage vectorization.
*/
static
void kernel_atax [[gnu::flatten, gnu::noinline]] (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  /* Initialize y to zero.  This is kept as a simple, contiguous loop
     so that the compiler can vectorize it easily. */
#pragma omp simd
  for (i = 0; i < _PB_N; i++)
    y[i] = SCALAR_VAL(0.0);

  /* Parallelize across rows of A (index i).
     We use an OpenMP array-section reduction on y to avoid data races:
     each thread accumulates partial results into a private copy of y,
     and OpenMP combines them at the end of the parallel region.

     - schedule(static): gives good load balance for regular loops.
     - If OpenMP is not enabled, this pragma is ignored and execution
       remains sequential, preserving original behavior.
   */
#pragma omp parallel for schedule(static) reduction(+:y[:_PB_N]) private(j)
  for (i = 0; i < _PB_M; i++)
    {
      /* Local accumulator for tmp[i]; kept in a register during the
         dot-product computation to minimize memory traffic. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);

      /* Local row pointer to improve data locality and enable the
         compiler to generate more efficient code. The restrict
         qualifiers express the fact that these pointers do not alias
         each other in this benchmark, which is true given the way
         PolyBench allocates A, x, y, and tmp. */
      DATA_TYPE * __restrict__ Ai      = A[i];
      DATA_TYPE * __restrict__ x_local = x;

      /* First pass: compute the dot product of the i-th row of A
         with x: tmp_i = sum_j Ai[j] * x_local[j].
         The 'omp simd' pragma encourages vectorization; the reduction
         clause tells the compiler that tmp_i is a scalar reduction. */
#pragma omp simd reduction(+:tmp_i)
      for (j = 0; j < _PB_N; j++)
        tmp_i += Ai[j] * x_local[j];

      /* Store the accumulated value in tmp[i] to preserve the
         original live-out semantics of the tmp array. */
      tmp[i] = tmp_i;

      /* Second pass over the same row: accumulate into y.
         Because of the OpenMP array reduction on y in the enclosing
         parallel loop, each thread updates its own private copy of y
         here, avoiding write conflicts.

         'omp simd' again encourages the compiler to vectorize this
         inner loop. */
#pragma omp simd
      for (j = 0; j < _PB_N; j++)
        y[j] += Ai[j] * tmp_i;
    }
#pragma endscop
}


